from cryptography.fernet import Fernet

from app.core.config import settings

# Module-level singleton — key is stable for the process lifetime.
# Constructed once at import time; ValueError raised here if ENCRYPTION_KEY is malformed.
_fernet: Fernet | None = None


def _get_fernet() -> Fernet:
    global _fernet
    if _fernet is None:
        _fernet = Fernet(settings.ENCRYPTION_KEY.encode())
    return _fernet


def encrypt(plaintext: str) -> str:
    """Return Fernet-encrypted ciphertext as a UTF-8 string."""
    return _get_fernet().encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str:
    """Decrypt a Fernet ciphertext. Raises InvalidToken on bad key or corruption."""
    return _get_fernet().decrypt(ciphertext.encode()).decode()
